                        /** @example false */
                        execution_payload_blinded: boolean;
                        /** @example 12345 */
                        execution_payload_value: string;
                        /** @example 12345 */
                        consensus_block_value: string;
                        data: components["schemas"]["BlockContents"] | components["schemas"]["Electra-BlockContents"] | components["schemas"]["BlindedBeaconBlock"] | components["schemas"]["Deneb-BlockContents"] | components["schemas"]["Deneb-BlindedBeaconBlock"] | components["schemas"]["Capella-BeaconBlock"] | components["schemas"]["Capella-BlindedBeaconBlock"] | components["schemas"]["Bellatrix-BeaconBlock"] | components["schemas"]["Bellatrix-BlindedBeaconBlock"] | components["schemas"]["BeaconBlock"] | components["schemas"]["Phase0-BeaconBlock"];
